css:
.lists {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 24px;
  padding: 24px;
  font-family: system-ui, sans-serif;
  font-size: 17px;
}

.steps,
.ticks {
  margin: 0;
  padding-left: 28px;
}

.steps li,
.ticks li {
  margin-bottom: 8px;
}

.steps li::marker {
  color: #ea580c;
  font-weight: 700;
}

.ticks {
  list-style-type: "✓  ";
}

.ticks li::marker {
  color: #16a34a;
}
